package dev.atul.capsulemap;

import android.app.Activity;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.Manifest;
import android.content.pm.PackageManager;
import android.content.Context;
import android.graphics.*;
import android.hardware.camera2.*;
import android.net.wifi.WifiManager;
import android.view.*;
import android.widget.Toast;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class MainActivity extends Activity {
  final Handler main = new Handler(Looper.getMainLooper());
  volatile String prompt = "ocean waves";
  volatile String cameraStatus = "Checking camera API…";
  volatile boolean guides = true;
  volatile float[] corners = {0.15f,0.15f,0.85f,0.15f,0.85f,0.85f,0.15f,0.85f};
  String pin; String ip = "unknown";
  MapView map;
  ServerSocket server;
  CameraDevice opened;
  @Override public void onCreate(Bundle b) { super.onCreate(b); getWindow().getDecorView().setSystemUiVisibility(5894|1024|512); pin=String.format(Locale.US,"%06d",new java.security.SecureRandom().nextInt(1000000)); map=new MapView(this); setContentView(map); ip=localIp(); startServer(); checkCamera(); }
  @Override public void onDestroy(){try{if(server!=null)server.close(); if(opened!=null)opened.close();}catch(Exception ignored){}super.onDestroy();}
  String localIp(){ try {WifiManager w=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);int a=w.getConnectionInfo().getIpAddress();if(a!=0)return String.format(Locale.US,"%d.%d.%d.%d",a&255,a>>8&255,a>>16&255,a>>24&255);}catch(Exception ignored){} try{Enumeration<NetworkInterface> es=NetworkInterface.getNetworkInterfaces();while(es.hasMoreElements()){NetworkInterface ni=es.nextElement();for(InterfaceAddress ia:ni.getInterfaceAddresses()){InetAddress a=ia.getAddress();if(a instanceof Inet4Address&&!a.isLoopbackAddress()&&!a.isLinkLocalAddress())return a.getHostAddress();}}}catch(Exception ignored){}return "unknown";}
  void checkCamera(){try{CameraManager mgr=(CameraManager)getSystemService(Context.CAMERA_SERVICE); String[] ids=mgr.getCameraIdList();if(ids.length==0){cameraStatus="Camera2: zero app-visible cameras. Nebula calibration camera may be private.";map.invalidate();return;}StringBuilder sb=new StringBuilder("Camera2 IDs: ");for(String id:ids){CameraCharacteristics c=mgr.getCameraCharacteristics(id);Integer face=c.get(CameraCharacteristics.LENS_FACING);sb.append(id).append(" (facing ").append(face).append(") ");}cameraStatus=sb.toString()+" • Opening first camera…";map.invalidate();if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},9);return;}tryOpen(ids[0]);}catch(Exception e){cameraStatus="Camera2 query failed: "+e.getClass().getSimpleName()+": "+e.getMessage();map.invalidate();}}
  @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==9){if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)checkCamera();else{cameraStatus="Camera listed; CAMERA permission denied. Grant it to test opening.";map.invalidate();}}}
  void tryOpen(String id){try{CameraManager mgr=(CameraManager)getSystemService(Context.CAMERA_SERVICE);mgr.openCamera(id,new CameraDevice.StateCallback(){@Override public void onOpened(CameraDevice d){opened=d;cameraStatus="Camera2 ID "+id+" opened successfully; image stream untested. This may not be the calibration camera.";map.invalidate();d.close();opened=null;}@Override public void onDisconnected(CameraDevice d){cameraStatus="Camera "+id+" disconnected";map.invalidate();d.close();}@Override public void onError(CameraDevice d,int error){cameraStatus="Camera "+id+" open failed (code "+error+")";map.invalidate();d.close();}},main);}catch(Exception e){cameraStatus="Camera "+id+" open error: "+e.getClass().getSimpleName()+": "+e.getMessage();map.invalidate();}}
  void startServer(){new Thread(new Runnable(){public void run(){try{server=new ServerSocket(8765);while(!server.isClosed()){final Socket socket=server.accept();socket.setSoTimeout(4000);new Thread(new Runnable(){public void run(){handle(socket);}}).start();}}catch(IOException e){if(server==null||!server.isClosed()){cameraStatus="Phone server failed: "+e.getMessage();main.post(new Runnable(){public void run(){map.invalidate();}});}}}}).start();}
  void handle(Socket s){try(Socket socket=s){BufferedReader reader=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));String first=reader.readLine();if(first==null)return;String[] parts=first.split(" ");if(parts.length<2)return;String path=parts[1];int len=0;String line;while((line=reader.readLine())!=null&&!line.isEmpty()){if(line.toLowerCase(Locale.US).startsWith("content-length:"))len=Math.min(8192,Integer.parseInt(line.substring(15).trim()));}char[] buf=new char[len];int n=0;while(n<len){int k=reader.read(buf,n,len-n);if(k<0)break;n+=k;}String body=new String(buf,0,n);String mime="application/json";String result;int status=200;
   if(path.equals("/")){mime="text/html; charset=utf-8";result=HTML;}
   else if(path.equals("/state")){JSONObject o=new JSONObject();o.put("prompt",prompt);o.put("corners",new JSONArray(corners));o.put("guides",guides);o.put("camera",cameraStatus);result=o.toString();}
   else if(path.equals("/update")&&parts[0].equals("POST")){JSONObject o=new JSONObject(body);if(!pin.equals(o.optString("pin"))){status=403;result="{\"error\":\"Wrong PIN\"}";}else{if(o.has("prompt"))prompt=o.optString("prompt").substring(0,Math.min(180,o.optString("prompt").length()));if(o.has("guides"))guides=o.optBoolean("guides");JSONArray a=o.optJSONArray("corners");if(a!=null&&a.length()==8){float[] v=new float[8];for(int i=0;i<8;i++)v[i]=Math.max(0,Math.min(1,(float)a.getDouble(i)));corners=v;}main.post(new Runnable(){public void run(){map.invalidate();}});result="{\"ok\":true}";}}
   else{status=404;result="{\"error\":\"Not found\"}";}
   byte[] out=result.getBytes(StandardCharsets.UTF_8);OutputStream stream=s.getOutputStream();stream.write(("HTTP/1.1 "+status+" "+(status==200?"OK":"Error")+"\r\nContent-Type: "+mime+"\r\nContent-Length: "+out.length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));stream.write(out);stream.flush();
  }catch(Exception ignored){}}
  final class MapView extends View {
   Paint p=new Paint(3); long start=System.currentTimeMillis(); MapView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
   @Override protected void onDraw(Canvas canvas){int w=getWidth(),h=getHeight();canvas.drawColor(Color.BLACK);float[] c=corners;float[] dst={c[0]*w,c[1]*h,c[2]*w,c[3]*h,c[4]*w,c[5]*h,c[6]*w,c[7]*h};Path mask=new Path();mask.moveTo(dst[0],dst[1]);for(int i=2;i<8;i+=2)mask.lineTo(dst[i],dst[i+1]);mask.close();Matrix m=new Matrix();m.setPolyToPoly(new float[]{0,0,1000,0,1000,600,0,600},0,dst,0,4);canvas.save();canvas.clipPath(mask);canvas.concat(m);float t=(System.currentTimeMillis()-start)/1000f;String s=prompt.toLowerCase(Locale.US);boolean wave=s.contains("wave")||s.contains("ocean")||s.contains("water");boolean stars=s.contains("star")||s.contains("space")||s.contains("galaxy");boolean grid=s.contains("grid")||s.contains("matrix")||s.contains("cyber");p.setStyle(Paint.Style.FILL);p.setColor(wave?Color.rgb(1,17,43):stars?Color.rgb(12,5,35):grid?Color.rgb(2,19,16):Color.rgb(27,7,35));canvas.drawRect(0,0,1000,600,p);
    if(wave){for(int j=0;j<18;j++){Path path=new Path();for(int x=0;x<=1000;x+=10){float y=90+j*28+(float)Math.sin(x*.012+t*1.4+j*.42)*22;if(x==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setColor(Color.HSVToColor(new float[]{190+3*j,.75f,.3f+.03f*j}));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);canvas.drawPath(path,p);}}
    else if(stars){for(int i=0;i<130;i++){float x=(i*7919%997),y=(i*5701%593),r=1+(i%4);p.setColor(Color.argb(80+(int)(175*Math.abs(Math.sin(t*1.8+i))),170+i%85,170+i%65,255));p.setStyle(Paint.Style.FILL);canvas.drawCircle(x,y,r,p);}}
    else if(grid){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.rgb(36,245,176));for(int i=0;i<22;i++){float x=(i*54+t*24)%1100;canvas.drawLine(x,0,x-100,600,p);}for(int j=0;j<14;j++){float y=(j*50+t*18)%650;canvas.drawLine(0,y,1000,y,p);}}
    else{for(int j=0;j<16;j++){float x=500+(float)Math.sin(t*.7+j*2.4)*(50+j*22),y=300+(float)Math.cos(t*.8+j*2.4)*(30+j*15);p.setStyle(Paint.Style.FILL);p.setColor(Color.HSVToColor(new float[]{(j*24+(int)(t*12))%360,.72f,.85f}));canvas.drawCircle(x,y,12+j*2,p);}}canvas.restore();
    if(guides){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(Color.WHITE);canvas.drawPath(mask,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<8;i+=2){p.setColor(Color.YELLOW);canvas.drawCircle(dst[i],dst[i+1],9,p);}p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(Math.max(16,h*.026f));p.setColor(Color.WHITE);canvas.drawText("CAPSULE MAP  •  "+ip+":8765  •  PIN "+pin,25,35,p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(Math.max(13,h*.021f));canvas.drawText(cameraStatus.length()>110?cameraStatus.substring(0,110):cameraStatus,25,h-24,p);}postInvalidateDelayed(33);
   }
   @Override public boolean onKeyDown(int k,android.view.KeyEvent e){if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER){guides=!guides;invalidate();return true;}return super.onKeyDown(k,e);}
  }
  static final String HTML="\n<!doctype html><html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Capsule Map</title><style>body{margin:0;background:#10131b;color:#eef2fa;font:16px system-ui;padding:22px;max-width:650px;margin:auto}h1{font-size:28px}p{color:#a9b2c4;line-height:1.5}label{display:block;margin:20px 0 8px}textarea,input,button{box-sizing:border-box;font:inherit}textarea,input{background:#232936;color:white;border:1px solid #526079;border-radius:9px;padding:12px;width:100%}button{background:#638bff;border:0;color:#10131b;border-radius:9px;padding:13px 18px;font-weight:700;margin:10px 8px 10px 0}canvas{width:100%;touch-action:none;border-radius:12px;background:#050507;border:1px solid #526079}small{color:#9aa9bf}</style></head><body><h1>Capsule Map</h1><p>Connect your phone and projector to the same Wi-Fi. Enter the PIN shown on the projection. Drag the four corners below to match your physical area.</p><label>Projector PIN</label><input id=\"pin\" inputmode=\"numeric\" maxlength=\"6\" placeholder=\"6-digit PIN\"><label>Effect prompt</label><textarea id=\"prompt\" rows=\"3\">ocean waves</textarea><p>Built-in effects respond to \u201cocean / waves\u201d, \u201cstars / galaxy\u201d, and \u201cgrid / cyber\u201d. Other prompts use color particles. This prototype does not call an AI model.</p><label>Mapping corners</label><canvas id=\"cv\" width=\"600\" height=\"360\"></canvas><div><button id=\"send\">Project</button><button id=\"guides\">Hide / show guides</button><button id=\"reset\">Reset corners</button></div><p id=\"msg\"></p><small id=\"camera\"></small><script>\nlet c=[.15,.15,.85,.15,.85,.85,.15,.85],g=true,cv=document.getElementById('cv'),ctx=cv.getContext('2d'),active=-1;document.getElementById('pin').value=localStorage.getItem('capsulePin')||'';function draw(){ctx.fillStyle='#060b15';ctx.fillRect(0,0,600,360);ctx.beginPath();for(let i=0;i<4;i++){let x=c[2*i]*600,y=c[2*i+1]*360;if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y)}ctx.closePath();ctx.fillStyle='#3452a7';ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=2;ctx.stroke();for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(c[2*i]*600,c[2*i+1]*360,11,0,7);ctx.fillStyle='#ffd859';ctx.fill();ctx.fillStyle='#111';ctx.font='bold 13px system-ui';ctx.fillText(''+(i+1),c[2*i]*600-4,c[2*i+1]*360+5)}}draw();function pos(e){let r=cv.getBoundingClientRect();return [(e.clientX-r.left)*600/r.width,(e.clientY-r.top)*360/r.height]}cv.onpointerdown=e=>{let [x,y]=pos(e),d=1e9;for(let i=0;i<4;i++){let z=Math.hypot(x-c[2*i]*600,y-c[2*i+1]*360);if(z<d){d=z;active=i}}cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(active<0)return;let [x,y]=pos(e);c[2*active]=Math.max(0,Math.min(1,x/600));c[2*active+1]=Math.max(0,Math.min(1,y/360));draw()};cv.onpointerup=()=>active=-1;async function send(){let pin=document.getElementById('pin').value;localStorage.setItem('capsulePin',pin);try{let r=await fetch('/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pin,prompt:document.getElementById('prompt').value,corners:c,guides:g})});document.getElementById('msg').textContent=r.ok?'Projected. Adjust corners and tap Project again.':`Failed: ${r.status}. Check the PIN.`}catch(e){document.getElementById('msg').textContent=e.message}}document.getElementById('send').onclick=send;document.getElementById('guides').onclick=()=>{g=!g;send()};document.getElementById('reset').onclick=()=>{c=[.15,.15,.85,.15,.85,.85,.15,.85];draw();send()};fetch('/state').then(r=>r.json()).then(v=>{c=v.corners;g=v.guides;document.getElementById('prompt').value=v.prompt;document.getElementById('camera').textContent='Camera diagnostic: '+v.camera;draw()});</script></body></html>\n";
}
